// Core tests: the 19 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation-order, and property cases from
// the SPEC's tests section. Every expected value below was computed by
// hand from the SPEC's pinned rules (integer centimetres, TRIM = 10,
// drops-per-roll, waste inflates strips before rolls).

import assert from "node:assert/strict";
import test from "node:test";
import { formatAreaM2, run } from "../public/js/core/wallpaper.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  wallMode: "perimeter",
  perimeterM: "12",
  heightM: "2.5",
  rollWidthM: "0.53",
  rollLengthM: "10.05",
  patternRepeatCm: "0",
  openingsMode: "none",
  wastePercent: "0",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

const SCHEMA = { code: "SCHEMA", field: null, row: null };

test("schema: extra key, missing key, wrong types, array, null, accessor", () => {
  assert.deepEqual(errorOf({ ...base, extra: "1" }), SCHEMA);
  const missing = { ...base };
  delete missing.wastePercent;
  assert.deepEqual(errorOf(missing), SCHEMA);
  assert.deepEqual(errorOf({ ...base, perimeterM: 12 }), SCHEMA);
  assert.deepEqual(errorOf({ ...base, wallMode: 1 }), SCHEMA);
  assert.deepEqual(errorOf(["12"]), SCHEMA);
  assert.deepEqual(errorOf(null), SCHEMA);
  assert.deepEqual(errorOf("12"), SCHEMA);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "perimeterM", {
    enumerable: true,
    get() {
      return "12";
    },
  });
  assert.deepEqual(errorOf(withGetter), SCHEMA);
});

test("schema: keys belonging to another mode are SCHEMA", () => {
  // perimeter mode carrying a walls array
  assert.deepEqual(errorOf({ ...base, walls: [{ widthM: "4", heightM: "2.5" }] }), SCHEMA);
  // openingsMode none carrying an area value
  assert.deepEqual(errorOf({ ...base, openingsAreaM2: "3" }), SCHEMA);
  // walls mode missing its walls key
  assert.deepEqual(
    errorOf({
      wallMode: "walls",
      rollWidthM: "0.53",
      rollLengthM: "10.05",
      patternRepeatCm: "0",
      openingsMode: "none",
      wastePercent: "0",
    }),
    SCHEMA,
  );
});

test("schema: a malformed row element carries its 1-based row, field null", () => {
  const wallsBase = {
    wallMode: "walls",
    rollWidthM: "0.53",
    rollLengthM: "10.05",
    patternRepeatCm: "0",
    openingsMode: "none",
    wastePercent: "0",
  };
  assert.deepEqual(
    errorOf({ ...wallsBase, walls: [{ widthM: "4", heightM: "2.5", depthM: "1" }] }),
    { code: "SCHEMA", field: null, row: 1 },
  );
  assert.deepEqual(
    errorOf({
      ...wallsBase,
      walls: [
        { widthM: "4", heightM: "2.5" },
        { widthM: "3" },
      ],
    }),
    { code: "SCHEMA", field: null, row: 2 },
  );
  assert.deepEqual(errorOf({ ...wallsBase, walls: [{ widthM: 4, heightM: "2.5" }] }), {
    code: "SCHEMA",
    field: null,
    row: 1,
  });
});

test("enum: wallMode is judged before openingsMode; mode errors precede field errors", () => {
  assert.deepEqual(errorOf({ ...base, wallMode: "PERIMETER" }), {
    code: "ENUM",
    field: "wallMode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, openingsMode: "some" }), {
    code: "ENUM",
    field: "openingsMode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, wallMode: "x", openingsMode: "y" }), {
    code: "ENUM",
    field: "wallMode",
    row: null,
  });
});

test("mode combination precedes per-field checks, but schema precedes it", () => {
  const combo = {
    wallMode: "walls",
    walls: [{ widthM: "4", heightM: "2.5" }],
    rollWidthM: "x",
    rollLengthM: "10.05",
    patternRepeatCm: "0",
    openingsMode: "list",
    openings: [{ widthM: "0.9", heightM: "2.1" }],
    wastePercent: "0",
  };
  assert.deepEqual(errorOf(combo), { code: "MODE_COMBINATION", field: "openingsMode", row: null });
  const comboBadRow = {
    ...combo,
    rollWidthM: "0.53",
    openings: [{ widthM: "0.9" }],
  };
  assert.deepEqual(errorOf(comboBadRow), { code: "SCHEMA", field: null, row: 1 });
});

test("field order: perimeterM before heightM before roll fields", () => {
  assert.deepEqual(errorOf({ ...base, perimeterM: "0", heightM: "x" }), {
    code: "RANGE",
    field: "perimeterM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, heightM: "2.505", rollWidthM: "x" }), {
    code: "DECIMAL_FORMAT",
    field: "heightM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rollWidthM: "0.05" }), {
    code: "RANGE",
    field: "rollWidthM",
    row: null,
  });
});

test("per-field checks: INPUT_LIMIT, UNICODE, EMPTY, format, range", () => {
  assert.deepEqual(errorOf({ ...base, perimeterM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "perimeterM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, heightM: "\uD800" }), {
    code: "UNICODE",
    field: "heightM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rollLengthM: "" }), {
    code: "EMPTY",
    field: "rollLengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, patternRepeatCm: "1.5" }), {
    code: "INTEGER_FORMAT",
    field: "patternRepeatCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, patternRepeatCm: "-1" }), {
    code: "INTEGER_FORMAT",
    field: "patternRepeatCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, patternRepeatCm: "201" }), {
    code: "RANGE",
    field: "patternRepeatCm",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, wastePercent: "10.5" }), {
    code: "INTEGER_FORMAT",
    field: "wastePercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, wastePercent: "51" }), {
    code: "RANGE",
    field: "wastePercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rollWidthM: " 0.53" }), {
    code: "DECIMAL_FORMAT",
    field: "rollWidthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rollWidthM: "0.09" }), {
    code: "RANGE",
    field: "rollWidthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rollLengthM: "0.99" }), {
    code: "RANGE",
    field: "rollLengthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, perimeterM: "200.01" }), {
    code: "RANGE",
    field: "perimeterM",
    row: null,
  });
});

test("walls rows: empty list, row limit, and first row error wins with its row number", () => {
  const wallsBase = {
    wallMode: "walls",
    rollWidthM: "0.53",
    rollLengthM: "10.05",
    patternRepeatCm: "0",
    openingsMode: "none",
    wastePercent: "0",
  };
  assert.deepEqual(errorOf({ ...wallsBase, walls: [] }), {
    code: "EMPTY",
    field: "walls",
    row: null,
  });
  const thirteen = Array.from({ length: 13 }, () => ({ widthM: "1", heightM: "2.5" }));
  assert.deepEqual(errorOf({ ...wallsBase, walls: thirteen }), {
    code: "ROW_LIMIT",
    field: "walls",
    row: null,
  });
  assert.deepEqual(
    errorOf({
      ...wallsBase,
      walls: [
        { widthM: "4", heightM: "2.5" },
        { widthM: "0", heightM: "2.5" },
      ],
    }),
    { code: "RANGE", field: "widthM", row: 2 },
  );
  assert.deepEqual(
    errorOf({
      ...wallsBase,
      walls: [
        { widthM: "4", heightM: "2.505" },
        { widthM: "0", heightM: "2.5" },
      ],
    }),
    { code: "DECIMAL_FORMAT", field: "heightM", row: 1 },
  );
  // widthM is checked before heightM within a row
  assert.deepEqual(errorOf({ ...wallsBase, walls: [{ widthM: "x", heightM: "0" }] }), {
    code: "DECIMAL_FORMAT",
    field: "widthM",
    row: 1,
  });
});

test("openings rows: empty list, row limit, row errors carry the row number", () => {
  assert.deepEqual(errorOf({ ...base, openingsMode: "list", openings: [] }), {
    code: "EMPTY",
    field: "openings",
    row: null,
  });
  const twentyOne = Array.from({ length: 21 }, () => ({ widthM: "0.1", heightM: "0.1" }));
  assert.deepEqual(errorOf({ ...base, openingsMode: "list", openings: twentyOne }), {
    code: "ROW_LIMIT",
    field: "openings",
    row: null,
  });
  assert.deepEqual(
    errorOf({
      ...base,
      openingsMode: "list",
      openings: [
        { widthM: "0.9", heightM: "2.1" },
        { widthM: "1", heightM: "0" },
      ],
    }),
    { code: "RANGE", field: "heightM", row: 2 },
  );
});

test("opening width at the perimeter and total area over the wall use distinct fields", () => {
  // Equal opening and wall heights pass the height check.
  assert.deepEqual(
    errorOf({
      ...base,
      openingsMode: "list",
      openings: [{ widthM: "12", heightM: "2.5" }],
    }),
    { code: "OPENINGS_EXCEED_WALL", field: "openings", row: null },
  );
  assert.deepEqual(errorOf({ ...base, openingsMode: "area", openingsAreaM2: "30.01" }), {
    code: "OPENINGS_EXCEED_WALL",
    field: "openingsAreaM2",
    row: null,
  });
});

test("strip too long in walls mode names the first offending wall row", () => {
  const outcome = run({
    wallMode: "walls",
    walls: [
      { widthM: "4", heightM: "2.5" },
      { widthM: "3", heightM: "3" },
    ],
    rollWidthM: "0.53",
    rollLengthM: "3",
    patternRepeatCm: "0",
    openingsMode: "none",
    wastePercent: "0",
  });
  assert.deepEqual(outcome, {
    ok: false,
    error: { code: "STRIP_TOO_LONG", field: "rollLengthM", row: 2 },
  });
  // the shortest legal roll still cannot fit a 260 cm strip
  assert.deepEqual(errorOf({ ...base, rollLengthM: "1" }), {
    code: "STRIP_TOO_LONG",
    field: "rollLengthM",
    row: null,
  });
});

test("valid upper endpoints: perimeter 200 m, repeat 200, waste 50, area equal to gross", () => {
  const wide = run({ ...base, perimeterM: "200" });
  assert.equal(wide.ok, true);
  assert.equal(wide.result.strips, 378); // ceil(20000 / 53)
  assert.equal(wide.result.rolls, 126); // ceil(378 / 3)

  const repeatMax = run({ ...base, patternRepeatCm: "200" });
  assert.equal(repeatMax.ok, true);
  assert.equal(repeatMax.result.walls[0].stripLengthCm, 400); // ceil(260/200)*200
  assert.equal(repeatMax.result.walls[0].dropsPerRoll, 2); // floor(1005/400)
  assert.equal(repeatMax.result.rolls, 12); // ceil(23/2)

  const wasteMax = run({ ...base, wastePercent: "50" });
  assert.equal(wasteMax.ok, true);
  assert.equal(wasteMax.result.walls[0].stripsWithWaste, 35); // ceil(23*150/100)
  assert.equal(wasteMax.result.rolls, 12); // ceil(35/3)

  const areaEqual = run({ ...base, openingsMode: "area", openingsAreaM2: "30" });
  assert.equal(areaEqual.ok, true);
  assert.equal(areaEqual.result.netWallAreaM2, "0.00");
  assert.equal(areaEqual.result.strips, 23); // area mode never deducts strips

  const areaZero = run({ ...base, openingsMode: "area", openingsAreaM2: "0" });
  assert.equal(areaZero.ok, true);
  assert.equal(areaZero.result.openingsAreaM2, "0.00");
});

test("walls mode with area deduction: gross, openings and net areas", () => {
  assert.deepEqual(
    run({
      wallMode: "walls",
      walls: [{ widthM: "4", heightM: "2.5" }],
      rollWidthM: "0.53",
      rollLengthM: "10.05",
      patternRepeatCm: "0",
      openingsMode: "area",
      openingsAreaM2: "5",
      wastePercent: "0",
    }),
    {
      ok: true,
      result: {
        walls: [
          {
            index: 1,
            widthCm: 400,
            openingsWidthCm: 0,
            effectiveWidthCm: 400,
            strips: 8,
            stripLengthCm: 260,
            dropsPerRoll: 3,
            stripsWithWaste: 8,
            rolls: 3,
          },
        ],
        strips: 8,
        stripsWithWaste: 8,
        rolls: 3,
        grossWallAreaM2: "10.00",
        openingsAreaM2: "5.00",
        netWallAreaM2: "5.00",
      },
    },
  );
});

test("waste inflates each wall separately before its rolls are counted", () => {
  const outcome = run({
    wallMode: "walls",
    walls: [
      { widthM: "4", heightM: "2.5" },
      { widthM: "3", heightM: "2.5" },
    ],
    rollWidthM: "0.53",
    rollLengthM: "10.05",
    patternRepeatCm: "0",
    openingsMode: "none",
    wastePercent: "10",
  });
  assert.equal(outcome.ok, true);
  // wall 1: ceil(8*1.1) = 9 -> ceil(9/3) = 3; wall 2: ceil(6*1.1) = 7 -> ceil(7/3) = 3
  assert.deepEqual(
    outcome.result.walls.map((wall) => [wall.stripsWithWaste, wall.rolls]),
    [
      [9, 3],
      [7, 3],
    ],
  );
  assert.equal(outcome.result.strips, 14);
  assert.equal(outcome.result.stripsWithWaste, 16);
  assert.equal(outcome.result.rolls, 6);
});

test("repeat and waste combine: strips inflate after the repeat rounding", () => {
  const outcome = run({ ...base, perimeterM: "10", patternRepeatCm: "32", wastePercent: "10" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.walls[0].stripLengthCm, 288);
  assert.equal(outcome.result.walls[0].stripsWithWaste, 21); // ceil(19*110/100)
  assert.equal(outcome.result.rolls, 7); // ceil(21/3)
});

test("area formatting rounds half up from exact cm² (AUTHOR-CHECK boundary values)", () => {
  assert.equal(formatAreaM2(101), "0.01");
  assert.equal(formatAreaM2(150), "0.02");
  assert.equal(formatAreaM2(50), "0.01");
  assert.equal(formatAreaM2(49), "0.00");
  assert.equal(formatAreaM2(0), "0.00");
  assert.equal(formatAreaM2(300000), "30.00");
  // through run(): a 1 cm x 101 cm wall has gross area exactly 101 cm²
  const outcome = run({ ...base, perimeterM: "0.01", heightM: "1.01" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.grossWallAreaM2, "0.01");
});

test("property: strip, length and drop invariants hold for the successful fixtures", () => {
  const successes = coreCases.filter((entry) => entry.expected.ok === true);
  assert.ok(successes.length >= 9);
  for (const entry of successes) {
    const outcome = run(entry.input);
    assert.equal(outcome.ok, true, entry.id);
    const rollWidthCm = Math.round(Number(entry.input.rollWidthM) * 100);
    const rollLengthCm = Math.round(Number(entry.input.rollLengthM) * 100);
    const repeat = Number(entry.input.patternRepeatCm);
    let strips = 0;
    let stripsWithWaste = 0;
    let rolls = 0;
    for (const wall of outcome.result.walls) {
      assert.equal(wall.effectiveWidthCm, wall.widthCm, entry.id);
      assert.ok(wall.strips * rollWidthCm >= wall.effectiveWidthCm, entry.id);
      assert.ok((wall.strips - 1) * rollWidthCm < wall.effectiveWidthCm, entry.id);
      if (repeat > 0) {
        const heightCm =
          entry.input.wallMode === "perimeter"
            ? Math.round(Number(entry.input.heightM) * 100)
            : Math.round(Number(entry.input.walls[wall.index - 1].heightM) * 100);
        assert.equal(wall.stripLengthCm % repeat, 0, entry.id);
        assert.ok(wall.stripLengthCm - repeat < heightCm + 10, entry.id);
        assert.ok(heightCm + 10 <= wall.stripLengthCm, entry.id);
      }
      assert.ok(wall.dropsPerRoll * wall.stripLengthCm <= rollLengthCm, entry.id);
      assert.ok((wall.dropsPerRoll + 1) * wall.stripLengthCm > rollLengthCm, entry.id);
      strips += wall.strips;
      stripsWithWaste += wall.stripsWithWaste;
      rolls += wall.rolls;
    }
    assert.equal(outcome.result.strips, strips, entry.id);
    assert.equal(outcome.result.stripsWithWaste, stripsWithWaste, entry.id);
    assert.equal(outcome.result.rolls, rolls, entry.id);
    // net = gross - openings at the displayed precision (fixtures are exact)
    const net = Number(outcome.result.grossWallAreaM2) - Number(outcome.result.openingsAreaM2);
    assert.equal(Number(outcome.result.netWallAreaM2), Math.round(net * 100) / 100, entry.id);
  }
});

test("run does not mutate its input", () => {
  const input = {
    wallMode: "walls",
    walls: [{ widthM: "4", heightM: "2.5" }],
    rollWidthM: "0.53",
    rollLengthM: "10.05",
    patternRepeatCm: "0",
    openingsMode: "none",
    wastePercent: "0",
  };
  const snapshot = JSON.stringify(input);
  run(input);
  assert.equal(JSON.stringify(input), snapshot);
});

test("PWP-02: malformed mode key sets precede invalid enum values", () => {
  const { perimeterM, heightM, ...noDimensions } = base;
  const row = { widthM: "1", heightM: "2" };
  const malformed = [
    { ...noDimensions, heightM, openingsMode: "oops" },
    { ...base, walls: [row], openingsMode: "oops" },
    { ...noDimensions, wallMode: "walls", openingsMode: "oops" },
    { ...base, wallMode: "oops", openingsMode: "area" },
    { ...base, wallMode: "oops", openingsMode: "list", openingsAreaM2: "2" },
    { ...base, wallMode: "oops", openingsMode: "none", openings: [row] },
    { ...noDimensions, wallMode: "oops", openingsMode: "oops" },
    { ...base, wallMode: "oops", openingsMode: "oops", openings: [row], openingsAreaM2: "2" },
  ];
  for (const input of malformed) assert.deepEqual(errorOf(input), SCHEMA, JSON.stringify(input));

  assert.deepEqual(
    errorOf({ ...base, openingsMode: "oops", openings: [row, { widthM: "1" }] }),
    { code: "SCHEMA", field: null, row: 2 },
  );
});

test("PWP-02: intact key sets still identify the first invalid enum", () => {
  const { perimeterM, heightM, ...withoutPerimeter } = base;
  const row = { widthM: "1", heightM: "2" };
  for (const [input, field] of [
    [{ ...base, openingsMode: "oops", openingsAreaM2: "2" }, "openingsMode"],
    [{ ...withoutPerimeter, wallMode: "walls", walls: [row], openingsMode: "oops", openings: [row] }, "openingsMode"],
    [{ ...withoutPerimeter, wallMode: "toString", walls: [row], openingsMode: "list", openings: [row] }, "wallMode"],
    [{ ...base, wallMode: "oops", openingsMode: "oops", openings: [row] }, "wallMode"],
  ]) {
    assert.deepEqual(errorOf(input), { code: "ENUM", field, row: null });
  }
});
